#!/usr/bin/env bash
# RankForge one-file repair + fix-pack. Run from the repo root:  bash rf-apply.sh
set -e
[ -d .github ] && [ -f sw.js ] || { echo "Run this from the repo root (where .github and sw.js are)."; exit 1; }
T=$(mktemp -d)
sed -n '/^__PAYLOAD__$/,$p' "$0" | tail -n +2 | base64 -d | tar xz -C "$T"
P="$T/payload"
echo "1) removing stray files flattened into the root..."
n=0; while read -r f; do [ -n "$f" ] && [ -f "$f" ] && rm -f "$f" && n=$((n+1)); done < "$P/delete.txt"; echo "   removed $n"
echo "2) restoring correct files..."
cp -r "$P/files/." .
chmod +x tools/sync-dist.sh 2>/dev/null || true
rm -f run.sh delete.txt restore.txt rf-repair
rm -rf "$T"
echo "3) checking the app..."
node tools/verify.js
node tools/verify.js | grep -q "ALL 9 CHECKS PASSED"
echo
echo "ALL DONE. Now run:  rm -f rf-apply.sh && git add -A && git commit -m 'RankForge fix-pack v2' && git push"
exit 0
__PAYLOAD__
